class TrieNode:
    def __init__(self):
        self.children = {}
        self.cost = float('inf')

class Solution:
    def minimumCost(self, target, words, costs):
        # Build Trie from words, record minimal cost for each word
        root = TrieNode()
        for word, cost in zip(words, costs):
            node = root
            for c in word:
                if c not in node.children:
                    node.children[c] = TrieNode()
                node = node.children[c]
            node.cost = min(node.cost, cost)

        n = len(target)
        INF = float('inf')
        # dp[i] = min cost to build target[i:] (bottom-up avoids deep recursion)
        dp = [INF] * (n + 1)
        dp[n] = 0

        for i in range(n - 1, -1, -1):
            node = root
            for j in range(i, n):
                c = target[j]
                if c not in node.children:
                    break
                node = node.children[c]
                if node.cost != INF and dp[j + 1] != INF:
                    dp[i] = min(dp[i], node.cost + dp[j + 1])

        return dp[0] if dp[0] != INF else -1
